/* Impulse in, mix 1: the energy of the tail in 50 ms windows, as the remaining energy (Schroeder's backward sum, which
 * is smooth where the windows themselves are not). The slope between -5 and -35 dB of it, taken to 60 dB: the time it
 * would take to fall that far. Returns -1 when the curve does not get there. */
static double vroom_t60(float decay, float damping)
{
    const pc_fxapp_t *t = app_by("velvet_room");
    float v[5] = { decay, 1, damping, 0.7f, 1 };
    const int frames = (int)((decay * 1.6f + 1.0f) * RATE), win = RATE / 20;
    float *x = calloc((size_t)frames * 2, sizeof(float));
    x[0] = x[1] = 1.0f;
    void *st = make(t, RATE, v);
    for (int off = 0; off < frames; off += BLK) t->process(st, x + 2 * off, frames - off < BLK ? frames - off : BLK);
    free(st);
    int nw = frames / win;
    double *e = calloc((size_t)nw, sizeof(double));
    for (int w = 0; w < nw; w++)
        for (int i = w * win; i < (w + 1) * win; i++) e[w] += (double)x[2 * i] * x[2 * i] + (double)x[2 * i + 1] * x[2 * i + 1];
    for (int w = nw - 2; w >= 0; w--) e[w] += e[w + 1];            /* what is left from the start of window w */
    double t5 = -1, t35 = -1;
    for (int w = 0; w < nw; w++) {
        if (t5 < 0 && e[w] < e[0] * pow(10.0, -0.5)) t5 = w * 0.05;
        if (t35 < 0 && e[w] < e[0] * pow(10.0, -3.5)) { t35 = w * 0.05; break; }
    }
    free(e); free(x);
    return t5 < 0 || t35 < 0 ? -1 : 2.0 * (t35 - t5);
}

/* Measured at damping 0, the energy decay lands about 15 % short of the nominal time (0.90, 1.70, 4.40 s for 1, 2, 5): that is
 * the source's own calibration of rt60_gain on this measure, kept (the port is bit-exact with its renders). So the bound is
 * [0.75, 1.15] x decay_s, and the three ratios must agree (one constant, not a drift with the decay). The figure at the
 * default damping is printed, not asserted. */
static void test_vroom_tail(void)
{
    static const float D[] = { 1, 2, 5 };
    double dflt[3], ratio[3];
    for (int k = 0; k < 3; k++) {
        double t60 = vroom_t60(D[k], 0.0f);
        dflt[k] = vroom_t60(D[k], 0.4f);
        ratio[k] = t60 / D[k];
        printf("velvet_room decay %g s, damping 0: 60 dB after %.2f s (x%.3f)\n", (double)D[k], t60, ratio[k]);
        CHECK(t60 > 0);
        CHECK(ratio[k] >= 0.75 && ratio[k] <= 1.15);
    }
    for (int k = 1; k < 3; k++) CHECK(fabs(ratio[k] - ratio[0]) <= 0.10);
    printf("fx vroom tail damping=0.4: %.2f %.2f %.2f s\n", dflt[0], dflt[1], dflt[2]);
}

/* the room does not depend on how the stream is cut into blocks: an impulse through blocks of 480, 7 and 1 frames gives the
 * same bits, with mix 0.3 -> 1 set at the same sample (0.5 s) in every run (the every-8 coefficient cadence and the ramps) */
static float *vroom_cut(int blk)
{
    const pc_fxapp_t *t = app_by("velvet_room");
    float v[5] = { 2, 1, 0.4f, 0.7f, 0.3f };
    const int frames = RATE, at = RATE / 2;
    float *x = calloc((size_t)frames * 2, sizeof(float));
    x[0] = x[1] = 1.0f;
    void *st = make(t, RATE, v);
    for (int off = 0; off < frames;) {
        int n = blk;
        if (off < at && off + n > at) n = at - off;       /* the set lands on the same sample whatever the cut */
        if (off + n > frames) n = frames - off;
        if (off == at) { v[4] = 1; v[0] = 3; t->set(st, v, 0x15); }
        t->process(st, x + 2 * off, n);
        off += n;
    }
    free(st);
    return x;
}

static void test_vroom_blocks(void)
{
    float *a = vroom_cut(480), *b = vroom_cut(7), *c = vroom_cut(1);
    size_t bytes = (size_t)RATE * 2 * sizeof(float);
    CHECK(memcmp(a, b, bytes) == 0);
    CHECK(memcmp(a, c, bytes) == 0);
    free(a); free(b); free(c);
}

/* the block holds the rate and the size it was made for (a smaller rate fits, a bigger one and another size do not);
 * rate() and reset() leave a state that sounds like a fresh one; bad input and extreme values stay finite */
static void test_vroom_block(void)
{
    const pc_fxapp_t *t = app_by("velvet_room");
    float v[5] = { 2, 1, 0.4f, 0.7f, 0.5f };
    void *st = make(t, RATE, v);
    CHECK(t->fits(st, 44100, v));
    CHECK(t->fits(st, 48000, v));
    CHECK(!t->fits(st, 96000, v));
    CHECK(!t->fits(st, 0, v));
    float w[5] = { 2, 1.5f, 0.4f, 0.7f, 0.5f };
    CHECK(!t->fits(st, 48000, w));            /* another size: a new block */
    w[1] = 1; w[0] = 7; w[2] = 1; w[3] = 0; w[4] = 1;
    CHECK(t->fits(st, 48000, w));             /* the other values are set() */
    float blk[2 * BLK], a[2 * BLK], b[2 * BLK];
    uint32_t seed = 99;
    for (int i = 0; i < 2 * BLK; i++) blk[i] = 0.5f * lcg_noise(&seed);
    void *fresh = make(t, RATE, v);
    for (int k = 0; k < 6; k++) { memcpy(a, blk, sizeof blk); t->process(st, a, BLK); }
    t->set(st, w, 0x1f);
    for (int k = 0; k < 6; k++) { memcpy(a, blk, sizeof blk); t->process(st, a, BLK); }
    t->set(st, v, 0x1f);
    t->reset(st);
    t->reset(st);
    t->reset(fresh);
    memcpy(a, blk, sizeof blk); t->process(st, a, BLK);
    memcpy(b, blk, sizeof blk); t->process(fresh, b, BLK);
    CHECK(memcmp(a, b, sizeof a) == 0);                /* reset = a fresh instance */
    t->rate(st, 44100);
    CHECK(t->fits(st, 44100, v));
    for (int k = 0; k < 20; k++) {                     /* hostile input */
        for (int i = 0; i < 2 * BLK; i++) a[i] = i % 97 == 0 ? NAN : i % 89 == 0 ? INFINITY : 4.0f * lcg_noise(&seed);
        t->process(st, a, BLK);
        for (int i = 0; i < 2 * BLK; i++) CHECK(isfinite(a[i]) && fabsf(a[i]) < 1000.0f);
    }
    float lim[2][5] = { { 0.2f, 0.5f, 1, 1, 1 }, { 20, 2, 0, 0, 0 } };
    for (int k = 0; k < 2; k++) {
        void *s2 = make(t, RATE, lim[k]);
        for (int j = 0; j < 100; j++) {
            for (int i = 0; i < 2 * BLK; i++) a[i] = 0.9f * lcg_noise(&seed);
            t->process(s2, a, BLK);
            for (int i = 0; i < 2 * BLK; i++) CHECK(isfinite(a[i]) && fabsf(a[i]) < 100.0f);
        }
        free(s2);
    }
    free(st); free(fresh);
}

static void test_vroom_ref(void)
{
    static const kv_t DEF[] = { { "decay_s", 2 }, { "size", 1 }, { "damping", 0.4f }, { "density", 0.7f }, { "mix", 0.3f } };   /* fx-lab's own defaults, stated */
    static const kv_t BIG[] = { { "decay_s", 5 }, { "size", 1.6f }, { "damping", 0.7f }, { "density", 0.3f }, { "mix", 1 } };
    static const kv_t OTHER[] = { { "decay_s", 5 }, { "size", 1.55f }, { "damping", 0.7f }, { "density", 0.3f }, { "mix", 1 } };
    static const kv_t DEF_WRONG[] = { { "decay_s", 2 }, { "size", 1 }, { "damping", 0.4f }, { "density", 0.7f }, { "mix", 0.5f } };
    ref_case("fdn_imp_def", "velvet_room", "in_imp.wav", "fdn_imp_def.wav", DEF, 5, DEF_WRONG, 5, 1e-3, true);
    ref_case("fdn_noise", "velvet_room", "in_noise.wav", "fdn_noise.wav", BIG, 5, OTHER, 5, 1e-3, true);
}
