int main(int argc, char **argv)
{
    g_self = argv[0];
    if (argc == 4 && !strcmp(argv[1], "--read-dir")) {   /* helper of test_dir_in_place_of_file: exit 0 = missing, 2 = read, 1 = FAIL */
        wavf_t w;
        return read_file_wav(argv[2], argv[3], &w) ? 2 : 0;
    }
    RUN(test_parts_hash);
    RUN(test_parts_line);
    RUN(test_parts_ln_cosh);
    RUN(test_parts_dc);
    RUN(test_wav_reader);
    RUN(test_compare_nonfinite);
    RUN(test_dir_in_place_of_file);
    RUN(test_tube_table);
    RUN(test_tube_level);
    RUN(test_tube_finite);
    RUN(test_tube_reset);
    RUN(test_tube_ref);
    RUN(test_vnd_table);
    RUN(test_vnd_mono_safe);
    RUN(test_vnd_impulse);
    RUN(test_vnd_ref);
#ifdef CONFIG_FX_VELVET_ROOM
    RUN(test_parts_rng);
    RUN(test_vroom_table);
    RUN(test_vroom_tail);
    RUN(test_vroom_blocks);
    RUN(test_vroom_block);
    RUN(test_vroom_ref);
#endif
    printf("fx ref: compared %d, skipped %d (renders in %s)\n", s_compared, s_skipped, *FXREF_DIR ? FXREF_DIR : "(none)");
    return 0;
}
